    question: '次の『徒然草』の一節を読んで、兼好法師が言いたいことを現代語でまとめなさい。\n\n「つれづれなるままに、日くらし硯にむかひて、心にうつりゆくよしなし事を、そこはかとなく書きつくれば、あやしうこそものぐるほしけれ。」',
