    explanation:
      '【何を聞かれているか】\n論語の一節「温故而知新、可以為師矣」を書き下し文にし、その意味を答える力が問われている。\n\n【なぜそうなるのか】\n「温」は「温める・繰り返し見直す」という意味で、「可以〜」は「〜することができる」という可能・許可を表す。\n\n【ステップ1】\n「温故而知新」を「故きを温めて新しきを知れば」と書き下す。\n\n【ステップ2】\n「可以為師矣」を「以て師と為るべし」と書き下し、「故（古いもの）」を丁寧に学び直すことで新しい発見や知恵が生まれ、人の師となる資格があるという意味を確認する。\n\n【答え】\n書き下し文：故きを温めて新しきを知れば、以て師と為るべし。\n意味：古いことを繰り返し学び、そこから新しい知識や意味を見出すことができれば、人の師となる資格がある。\n\n【確かめ】\n「可以〜」が「〜することができる・してもよい」という可能・許可の意味であることを再確認する。\n\n【よくあるまちがい】\n「温」を単に「あたためる」という物理的な意味と誤解し、「繰り返し学び直す」という意味を見落とさないこと。\n\n【ここが絶対】\n「温故知新」は論語（為政篇）に由来する、孔子の教育哲学を示す名言であることを押さえる。',
