    question: '次の古文中の尊敬語・謙譲語・丁寧語を正しく識別したものを選べ。\n\n【本文】\n「中宮様に申し上げたてまつるほどに、殿はいとめでたうおはしましたりき。」\n\nA: 「申し上げたてまつる」→丁寧語、「おはしましたりき」→謙譲語\nB: 「申し上げたてまつる」→謙譲語（中宮様を高める）、「おはしましたりき」→尊敬語（殿を高める）\nC: 「申し上げたてまつる」→尊敬語、「おはしましたりき」→丁寧語\nD: すべて丁寧語',
