      '【何を聞かれているか】\n荀子の一節「人の性は悪なり、其の善なるは偽なり。」から、「偽」の意味と荀子の思想を答える力が問われている。\n\n【なぜそうなるのか】\n荀子における「偽」は現代語の「偽り（うそ）」ではなく「人為・後天的な作為・努力」を意味する。\n\n【ステップ1】\n「人の性は悪なり」＝人間の本性は悪だという前提を確認する。\n\n【ステップ2】\n「其の善なるは偽なり」＝善いものになるのは人為（礼義・教育・修養）によるものだという主張を確認する。\n\n【答え】\nB\n\n【確かめ】\n「偽」が「嘘・虚偽」ではなく「人為・後天的な努力」を意味することを再確認する。\n\n【よくあるまちがい】\n「偽」を現代語の「うそ」の意味で読み、A・C・Dのような誤った解釈をしないこと。\n\n【ここが絶対】\n孟子の性善説と対立するが、両者とも教育・修養の重要性を認めている点では共通していることを押さえる。',
