    question: '次の漢文（書き下し文付き）を読み、返り点「レ点」と「一二点」の使い方について正しいものを選べ。\n\n【漢文】「不亦楽乎」\n【書き下し文】「また楽しからずや」\n\n「不」に施されている返り点の役割として正しいものを選べ。\n\nA: レ点は直前の一字に返って読む記号\nB: レ点は二字以上前の字に返って読む記号\nC: レ点がつくと、その字は飛ばして読む\nD: レ点は読む順序を数字で示す記号',
