      '【何を聞かれているか】\n森鴎外の作品と特徴について、正しい選択肢を選ぶ力が問われている。\n\n【なぜそうなるのか】\n鴎外のキャリアは前期（ロマン主義的作品）と後期（歴史小説）に分かれ、後期作品では人間の尊厳・死・判断の問題を掘り下げた。\n\n【ステップ1】\n前期がドイツ留学経験を生かした『舞姫』のようなロマン主義的作品であることを確認する。\n\n【ステップ2】\n後期が『阿部一族』（殉死の問題）、『山椒大夫』（人身売買と尊厳）、『高瀬舟』（安楽死・知足の問題）など歴史小説に転じたことを確認する。\n\n【答え】\nB\n\n【確かめ】\nA（生涯一貫してロマン主義は誤り）、C（漢文・古典の素養が深かった）、D（『舞姫』はドイツが舞台）が誤りであることを再確認する。\n\n【よくあるまちがい】\n鴎外を一貫したロマン主義作家と誤解し、後期の歴史小説への転換を見落とさないこと。\n\n【ここが絶対】\n森鴎外は陸軍軍医・文学者として双方で大きな業績を残したことを押さえる。',
