    explanation:
      '【何を聞かれているか】\n芥川龍之介の作品『羅生門』について、正しい選択肢を選ぶ力が問われている。\n\n【なぜそうなるのか】\n『羅生門』は今昔物語集を素材とし、極限状態における人間のエゴイズムを描いた作品である。\n\n【ステップ1】\n餓死するか盗賊になるかという極限状態に置かれた下人が、老婆の論理に感化されて強盗になるという過程を確認する。\n\n【ステップ2】\nこれが人間の極限におけるエゴイズム・悪の正当化のメカニズムを冷静に分析した作品であることを確認する。\n\n【答え】\nB\n\n【確かめ】\nA（自伝的作品ではない）、C（純愛小説ではない）、D（平安末期が舞台で江戸時代ではない）が誤りであることを再確認する。\n\n【よくあるまちがい】\n『羅生門』の舞台や内容を他の時代・ジャンルと混同しないこと。\n\n【ここが絶対】\n芥川は古典文学や西洋文学を素材として知的・心理的な主題を探求したことを押さえる。',
