    question: '太宰治の作品と特徴について、正しいものを選べ。\n\nA: 太宰治の作品は全体として明るい人間讃歌であり、社会への希望を描くものが多い\nB: 『人間失格』は太宰の最晩年作品で、社会に適応できない人間の自己告白・自己嫌悪と破滅を描いた私小説的傾向の強い作品だ\nC: 太宰治は生涯安定した生活を送り、作品も自身の幸福な家庭生活を反映している\nD: 太宰治は純粋な自然主義作家で、客観的な社会観察を淡々と記録した',
