    explanation:
      '【何を聞かれているか】\n川端康成の作品について、正しい選択肢を選ぶ力が問われている。\n\n【なぜそうなるのか】\n川端康成は日本の伝統美・余情・もののあわれを現代文学に昇華させ、1968年にノーベル文学賞を受賞した。\n\n【ステップ1】\n受賞スピーチ「美しい日本の私」で道元・明恵・西行・芭蕉・良寛など日本の詩歌・禅の美意識を論じたことを確認する。\n\n【ステップ2】\n代表作『雪国』が新潟の雪国を舞台に、日本の伝統的な余情・もののあわれ・虚無感を感覚的に表現していることを確認する。\n\n【答え】\nB\n\n【確かめ】\nA（西洋的写実主義は逆）、C（『雪国』は近代化批判でも社会派でもない）、D（自然主義ではなく新感覚派）が誤りであることを再確認する。\n\n【よくあるまちがい】\n川端康成を西洋的写実主義や自然主義の作家だと誤解しないこと。\n\n【ここが絶対】\n「国境の長いトンネルを抜けると雪国であった」という冒頭文が有名であることを押さえる。',
